        for(UUID card:cards)check(m.privateView(A).discard().stream().filter(c->c.instanceId().equals(card)).count()==1
            &&m.privateView(A).hand().stream().noneMatch(c->c.instanceId().equals(card))&&m.privateView(B).discard().stream().noneMatch(c->c.instanceId().equals(card)),"Concession lost/duplicated/misowned one actual Tome");
